let mut best_path = vec![];
for i in 0..n {
    for j in 0..n {
        let mut path = vec![grid[i][j]];
        if k == 1 {
            return path;
        }
        loop {
            let mut min_next_val = isize::MAX;
            let mut min_next_pos = None;
            for (di, dj) in [(0, 1), (0, -1), (1, 0), (-1, 0)] {
                let ni = i as isize + di;
                let nj = j as isize + dj;
                if ni >= 0 && ni < n as isize && nj >= 0 && nj < n as isize {
                    let val = grid[ni as usize][nj as usize];
                    if val < min_next_val {
                        min_next_val = val;
                        min_next_pos = Some((ni, nj));
                    }
                }
            }
            match min_next_pos {
                Some((ni, nj)) => {
                    path.push(grid[ni][nj]);
                    i = ni as usize;
                    j = nj as usize;
                    if path.len() == k as usize {
                        break;
                    }
                }
                None => break,
            }
        }
        if best_path.is_empty() || is_lexicographically_less(&path, &best_path) {
            best_path = path;
        }
    }
}
